import React from "react";
import { Link } from "react-router-dom";

function Navbar() {
  return (
    <nav className="navbar">

      <h2>🌊 Garbage Detection</h2>

      <ul>
        <li><Link to="/">Home</Link></li>
        <li><Link to="/">Upload</Link></li>
        <li><Link to="/about">About</Link></li>
      </ul>

    </nav>
  );
}

export default Navbar;
